const st = $getWorkflowStaticData('global');
st.ledger = st.ledger || {};
st.queue = st.queue || [];
st.curSeason = st.curSeason || null;
st.reports = st.reports || [];
// ---- build Mentalist priority queue ONCE (S4E21 -> S4 -> S5 -> S6 -> S7) ----
if (st.queue.length === 0 && !st.queueDone) {
  const bases = {
    4: 'https://tv10.egydead.live/episode/%d9%85%d8%b3%d9%84%d8%b3%d9%84-the-mentalist-%d8%a7%d9%84%d9%85%d9%88%d8%b3%d9%85-%d8%a7%d9%84%d8%b1%d8%a7%d8%a8%d8%b9-%d8%a7%d9%84%d8%ad%d9%84%d9%82%d8%a9-',
    5: 'https://tv10.egydead.live/episode/%d9%85%d8%b3%d9%84%d8%b3%d9%84-the-mentalist-%d8%a7%d9%84%d9%85%d9%88%d8%b3%d9%85-%d8%a7%d9%84%d8%ae%d8%a7%d9%85%d8%b3-%d8%a7%d9%84%d8%ad%d9%84%d9%82%d8%a9-',
    6: 'https://tv10.egydead.live/episode/%d9%85%d8%b3%d9%84%d8%b3%d9%84-the-mentalist-%d8%a7%d9%84%d9%85%d9%88%d8%b3%d9%85-%d8%a7%d9%84%d8%b3%d8%a7%d8%af%d8%b3-%d8%a7%d9%84%d8%ad%d9%84%d9%82%d8%a9-',
    7: 'https://tv10.egydead.live/episode/%d9%85%d8%b3%d9%84%d8%b3%d9%84-the-mentalist-%d8%a7%d9%84%d9%85%d9%88%d8%b3%d9%85-%d8%a7%d9%84%d8%b3%d8%a7%d8%a8%d8%b9-%d8%a7%d9%84%d8%ad%d9%84%d9%82%d8%a9-'
  };
  const counts = { 4: 24, 5: 22, 6: 22, 7: 13 };
  for (const s of [4, 5, 6, 7]) {
    const start = (s === 4) ? 21 : 1;
    for (let e = start; e <= counts[s]; e++) {
      st.queue.push({ series: 'The Mentalist', season: s, ep: e, url: bases[s] + e + '/', title: 'The Mentalist', type: 'tv' });
    }
  }
  st.queueDone = true;
}
// ---- pop next queued episode, else fall back to newest pool ----
if (st.queue.length > 0) {
  const q = st.queue.shift();
  return [{ json: { name: 'Q:' + q.series + ' S' + q.season + 'E' + q.ep, title: q.title, season: q.season, number: q.ep, epTitle: q.series + ' Season ' + q.season + ' Episode ' + q.ep, url: q.url, type: q.type, key: q.url, _queued: true } }];
}
// newest-at-top pool rotation
st.cursor = st.cursor || 0;
st.items = st.items || [];
const j = $input.first().json;
const titles = {};
for (const c of (j && Array.isArray(j.categories) ? j.categories : [])) {
  for (const it of (c.items || [])) {
    if (!it || !it.url) continue;
    if (!titles[it.url]) titles[it.url] = { title: it.title || '?', url: it.url, source: it.source || '?' };
  }
}
st.items = Object.values(titles);
if (st.items.length === 0) return [];
if (st.cursor >= st.items.length) st.cursor = 0;
const pick = st.items[st.cursor];
st.cursor++;
return [{ json: { name: 'P:', title: pick.title, url: pick.url, source: pick.source, key: pick.url, _queued: false } }];

const d = $input.first().json;
const det = d.details || {};
const prev = $('Pick next episode').first().json;
let eps = [];
if (prev._queued) {
  eps = [{ title: prev.title, epTitle: prev.epTitle, url: prev.url, number: prev.number, season: prev.season, type: 'tv', key: prev.key }];
} else if (Array.isArray(det.episodes) && det.episodes.length > 0) {
  eps = det.episodes.map(function (e) {
    const m = String(e.url || '').match(/[-/]s(\d+)e(\d+)/i);
    return { title: det.title || '?', epTitle: e.title || ('Episode ' + e.number), url: e.url, number: e.number || (m ? parseInt(m[2], 10) : null), season: m ? parseInt(m[1], 10) : prev.season || 1, type: 'tv', key: e.url };
  });
} else if (det.url) {
  const m = String(det.url || '').match(/[-/]s(\d+)e(\d+)/i);
  eps = [{ title: det.title || prev.title || '?', epTitle: det.title || '?', url: det.url, number: m ? parseInt(m[2], 10) : null, season: prev.season || (m ? parseInt(m[1], 10) : 1), type: (det.type || 'movie') === 'episode' ? 'tv' : 'movie', key: det.url }];
}
const st = $getWorkflowStaticData('global');
const cutoff = Date.now() - 14 * 24 * 3600 * 1000;
eps = eps.filter(function (e) { const l = st.ledger[e.key]; return !l || l.recheck === true || (l.updated && Date.parse(l.updated) < cutoff); });
return eps.slice(0, 8);

const strN = $input.first().json;
const streams = Array.isArray(strN.streams) ? strN.streams : [];
// pick first direct-playable stream (hls/mp4) to probe the REAL resolution; keep its referer (many HLS/CDN servers 403 without the right Referer)
let probeUrl = '';
let probeRef = '';
for (const s of streams) {
  const u = s.stream_url || '';
  if (/m3u8|\.mp4|master|index/i.test(u)) { probeUrl = u; probeRef = s.referer || ''; break; }
}
return [{ json: { probeUrl: probeUrl, probeRef: probeRef, streamCount: streams.length } }];

let body = '';
try { body = String($('Probe playlist').first().json || ''); } catch (e) { body = ''; }
const claimed = ($('Fetch streams').first().json.streams || []).map(function(s){ return s.quality_label || s.quality || null; }).filter(Boolean);
const resos = [];
const re = /RESOLUTION=(\d+)x(\d+)/gi; let m;
while ((m = re.exec(body)) !== null) resos.push(parseInt(m[2], 10));
const maxH = resos.length ? Math.max.apply(null, resos) : 0;
let actual = 'unverified';
if (maxH >= 1900) actual = '1080p';
else if (maxH >= 1230) actual = '720p';
else if (maxH >= 820) actual = '480p';
else if (maxH > 0) actual = '<=360p';
const bestClaim = claimed.map(function(c){ const q = String(c||'').match(/(\d{3,4})p/); return q ? parseInt(q[1],10) : 0; }).reduce(function(a,b){ return Math.max(a,b); }, 0);
const honest = (bestClaim && actual !== 'unverified') ? (maxH >= bestClaim - 1) : null;
return [{ json: { claimed: claimed.join(' | ') || 'none', actual_resolution: actual, max_height: maxH, honest_claim: honest, probe_source: body.slice(0, 80) } }];

let vr = { claimed: 'none', actual_resolution: 'unverified', honest_claim: null };
try { vr = $('Parse resolution').first().json; } catch (e) { vr = { claimed: 'none', actual_resolution: 'unverified', honest_claim: null }; }
let subsN = { ok: false, error: 'check subs failed' };
try {
  subsN = $('Check subs').first().json;
  if (subsN && typeof subsN.data === 'string' && subsN.data.length > 0) { try { subsN = JSON.parse(subsN.data); } catch (e2) {} }
} catch (e) {}
let strN = { streams: [] };
try { strN = $('Fetch streams').first().json; } catch (e) {}
let ep = { key: '?', title: '?', epTitle: '?' };
try { ep = $('Loop episodes').item.json || $json; } catch (e) {}
const streams = Array.isArray(strN?.streams) && strN.streams.length ? strN.streams : [{ provider: 'none', quality: null }];
const promptObj = {
  episode_key: ep.key || '?',
  show: ep.title || '?',
  episode: ep.epTitle || '?',
  arabic_subtitles: subsN && subsN.ok === true ? { found: true, lang: subsN.lang || 'ar' } : { found: false, note: subsN?.error || 'not found' },
  claimed_quality: vr.claimed || 'none',
  probed_resolution: vr.actual_resolution || 'unverified',
  honest_claim: vr.honest_claim || null,
  providers: streams.map(function (s) { return { name: s.server_name || s.quality_label || '?', quality: s.quality_label || (s.quality ? s.quality + 'p' : 'auto'), url: s.stream_url || '', type: s.stream_type || '' }; })
};
return [{ json: { prompt: 'You audit Arabic streaming sites for episode quality. Rules: (1) 1080p is REQUIRED if any provider truly delivers it; drop to 720p ONLY in the most extreme scenario; 480p or lower is NEVER acceptable as best. (2) A claim is a LIE if probed_resolution is lower than claimed_quality. (3) Rate each provider watermark_risk low/medium/high (known watermarked players: vidmoly, filemoon, streamwish, dood, vidoza, anything with url containing these; unknown iframe players = medium). (4) best_provider must be truthful + honest + lowest watermark risk. Answer ONLY JSON: {"has_arabic_subs": bool, "best_provider": "string", "best_quality": "verified 1080p" | "verified 720p" | "claimed 1080p unverified" | "claimed 720p unverified", "quality_score": 0-100, "watermark_risk": "low" | "medium" | "high", "verified_peak": bool, "notes": "string"}. Episode data: ' + JSON.stringify(promptObj) } }];

let g, verdict = null;
try { g = $('Ask Groq').first().json; verdict = JSON.parse(g.choices[0].message.content); } catch (e) {}
const st = $getWorkflowStaticData('global');
st.ledger = st.ledger || {}; st.reports = st.reports || [];
let ep = { key: '?', title: '?', epTitle: '?' };
try { ep = $('Loop episodes').item.json || $json; } catch (e) {}
if (!verdict || !ep || !ep.key) { return [{ json: { report: 'no', key: ep.key || '?' } }]; }
const key = ep.key;
const prev = st.ledger[key];
const peak = !!verdict.verified_peak && verdict.watermark_risk === 'low' && /1080|720/.test(String(verdict.best_quality));
st.ledger[key] = { score: verdict.quality_score || 0, best_provider: verdict.best_provider || '?', best_quality: verdict.best_quality || '?', subs: !!verdict.has_arabic_subs, wm: verdict.watermark_risk || 'unknown', peak: peak, updated: new Date().toISOString() };
const q = String(ep.name || ep.epTitle || ep.title || '');
const line = (ep.epTitle || ep.title || key) + ' | best=' + st.ledger[key].best_provider + ' ' + st.ledger[key].best_quality + ' | subs=' + (verdict.has_arabic_subs ? 'yes' : 'NO') + ' | wm=' + st.ledger[key].wm + ' | peak=' + (peak ? 'YES' : 'no');
st.reports.push({ t: new Date().toISOString(), type: 'episode', text: line, key: key });
let subject = '', body = '';
const isMentalist = /Mentalist S/i.test(q) || (ep.title === 'The Mentalist');
if (peak) { subject = (isMentalist ? 'Mentalist ' : 'Hunter ') + (ep.epTitle || ep.title || 'episode') + ': PEAK CONFIRMED'; body = 'PEAK QUALITY VERIFIED\n' + (ep.epTitle || ep.title || key) + '\nSeries: ' + (ep.title || '?') + '\nBest: ' + st.ledger[key].best_provider + ' (' + st.ledger[key].best_quality + ')\nArabic subs: ' + (verdict.has_arabic_subs ? 'YES' : 'NO') + '\nWatermark risk: ' + st.ledger[key].wm + '\nNotes: ' + (verdict.notes || ''); }
else if (prev && !prev.peak && peak) { subject = (isMentalist ? 'Mentalist ' : 'Hunter ') + (ep.epTitle || ep.title || 'episode') + ': UPGRADED TO PEAK'; body = 'Previously sub-peak, now PEAK:\n' + (ep.epTitle || ep.title || key) + '\nBest: ' + st.ledger[key].best_provider + ' (' + st.ledger[key].best_quality + ')\nWatermark risk: ' + st.ledger[key].wm; }
// every 10 QUEUED-Mentalist episodes -> sources report
let report = '';
if (ep._queued !== false || ep.title === 'The Mentalist') {
  st.mCounter = (st.mCounter || 0) + 1;
  if (st.mCounter % 10 === 0) {
    const last10 = st.reports.slice(-10).map(function (r) { return '- ' + r.text; }).join('\n');
    report = 'SOURCES REPORT (last 10 episodes)\n' + last10;
    st.reports.push({ t: new Date().toISOString(), type: 'report10', text: report, key: key });
  }
}
// per-season report
if (ep.season && st.curSeason && st.curSeason !== ep.season) {
  const prevSeason = st.curSeason;
  const lines = st.reports.filter(function (r) { return new RegExp('Season ' + prevSeason + ' ', 'i').test(String(r.text || '')); }).map(function (r) { return '- ' + r.text; });
  report = report + (report ? '\n\n' : '') + 'SEASON ' + prevSeason + ' FULL REPORT (' + prevSeason + ')\n' + (lines.slice(0, 40).join('\n') || 'no episodes recorded');
  st.reports.push({ t: new Date().toISOString(), type: 'season', text: report, key: key });
  st.curSeasonReported = prevSeason;
}
if (ep.season) st.curSeason = ep.season;
st.reports = st.reports.slice(-500);
if (!report && !subject) return [{ json: { report: 'no', key: key } }];
if (!subject) { subject = 'STREAMHUB HUNTER REPORT'; body = report; }
else if (report) { body = body + '\n\n---\n' + report; }
return [{ json: { report: 'yes', subject: subject, body: body, key: key } }];
